const link=(label,to,cls='button',attrs='')=>`<a href="#/${to}" class="${cls}" ${attrs}>${label}</a>`;
const button=(label,act,attrs='',cls='button')=>`<button type="button" class="${cls}" data-act="${act}" ${attrs}>${label}</button>`;
