 if(['rhythm-endless-v9','rhythm-three-lane-v11'].includes(r.mode))return `<div class="rhythm-result-stats"><span>정확도 <b>${Number(r.details.accuracy)||0}%</b></span><span>최대 콤보 <b>${Number(r.details.maxCombo)||0}</b></span><span>완료 패턴 <b>${Number(r.details.roundsCompleted)||0}</b></span><span>최고 속도 <b>${Number(r.details.maxBpm)||0} BPM</b></span></div><p class="small">완벽 ${Number(r.details.perfect)||0} · 좋아요 ${Number(r.details.good)||0} · 놓침 ${Number(r.details.misses)||0}</p>`;
 return '';
